export const THEMATA_FINDINGS_HTML = "<!doctype html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\r\n<meta name=\"robots\" content=\"noindex\">\r\n<title>Themata Findings</title>\r\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\">\r\n<style>\r\n/* Layout: one reading column in the Arete Library register, ink and gold, near square corners, tables scroll inside their own frames. */\r\n:root {\r\n  color-scheme: dark;\r\n  --ink: #0a1628;\r\n  --card: #111d30;\r\n  --gold: #c9a84c;\r\n  --gold-light: #e3c77a;\r\n  --text: #e0e0e0;\r\n  --warm: #e0d5b5;\r\n  --muted: #8a93a3;\r\n  --faint: #5a6475;\r\n  --hair: rgba(201, 168, 76, 0.2);\r\n  --hair-soft: rgba(201, 168, 76, 0.12);\r\n  --tint: rgba(201, 168, 76, 0.08);\r\n  --ok: #7fb58a;\r\n  --no: #c98a7a;\r\n  --serif: \"Cormorant Garamond\", Georgia, \"Times New Roman\", serif;\r\n  --sans: \"Inter\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\r\n  --mono: \"JetBrains Mono\", ui-monospace, \"SFMono-Regular\", Menlo, monospace;\r\n}\r\n* { box-sizing: border-box; }\r\nbody {\r\n  margin: 0;\r\n  background: var(--ink);\r\n  color: var(--text);\r\n  font-family: var(--sans);\r\n  font-size: 15px;\r\n  line-height: 1.65;\r\n  padding-inline: 16px;\r\n  padding-block: 40px 72px;\r\n  -webkit-font-smoothing: antialiased;\r\n}\r\n.page { max-width: 760px; margin: 0 auto; display: grid; gap: 56px; }\r\nsection { display: grid; gap: 18px; min-width: 0; }\r\n.kicker {\r\n  font-family: var(--mono);\r\n  font-size: 11px;\r\n  font-weight: 600;\r\n  letter-spacing: 2.4px;\r\n  text-transform: uppercase;\r\n  color: var(--gold);\r\n}\r\nh1, h2, h3 { font-family: var(--serif); color: #fff; text-wrap: balance; margin: 0; font-weight: 600; }\r\nh1 { font-size: clamp(34px, 6vw, 50px); line-height: 1.08; letter-spacing: 0.2px; }\r\nh2 { font-size: 28px; line-height: 1.2; }\r\nh3 { font-size: 21px; line-height: 1.25; }\r\np { margin: 0; max-width: 65ch; }\r\n.lede { font-family: var(--serif); font-size: 21px; line-height: 1.5; color: var(--warm); }\r\n.greek { font-family: var(--serif); font-style: italic; color: var(--gold-light); }\r\nem { color: var(--warm); }\r\ncode, .mono { font-family: var(--mono); font-size: 0.86em; color: var(--gold-light); }\r\n\r\nheader { display: grid; gap: 16px; }\r\n.status {\r\n  display: flex; flex-wrap: wrap; gap: 8px 16px; align-items: center;\r\n  border: 1px solid var(--hair); background: var(--tint);\r\n  border-radius: 2px; padding: 12px 16px; font-size: 13.5px; color: var(--warm);\r\n}\r\n.status strong { color: var(--gold); font-family: var(--mono); font-size: 11px; letter-spacing: 1.6px; text-transform: uppercase; }\r\n\r\n.question {\r\n  border-left: 3px solid var(--gold);\r\n  padding: 4px 0 4px 20px;\r\n  font-family: var(--serif); font-style: italic; font-size: 23px; line-height: 1.45; color: var(--warm);\r\n  max-width: 62ch;\r\n}\r\n\r\n.figures { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 12px; }\r\n.figure { border: 1px solid var(--hair-soft); background: var(--card); border-radius: 2px; padding: 18px 18px 16px; display: grid; gap: 6px; align-content: start; }\r\n.figure .num { font-family: var(--serif); font-size: 44px; line-height: 1; color: var(--gold); font-weight: 600; font-variant-numeric: tabular-nums; }\r\n.figure .of { font-family: var(--mono); font-size: 13px; color: var(--muted); margin-left: 4px; }\r\n.figure .what { font-size: 13.5px; color: var(--text); line-height: 1.45; }\r\n\r\n.findings { display: grid; gap: 14px; }\r\n.finding { border-left: 3px solid var(--gold); padding: 2px 0 2px 18px; display: grid; gap: 6px; }\r\n.finding h3 { font-size: 20px; }\r\n.finding p { color: var(--text); }\r\n\r\n.frame { overflow-x: auto; border: 1px solid var(--hair-soft); border-radius: 2px; background: var(--card); }\r\ntable { border-collapse: collapse; width: 100%; font-size: 13.5px; }\r\nth, td { text-align: left; padding: 10px 14px; border-bottom: 1px solid var(--hair-soft); vertical-align: top; }\r\ntr:last-child td { border-bottom: 0; }\r\nth { font-family: var(--mono); font-size: 11px; font-weight: 600; letter-spacing: 1.2px; text-transform: uppercase; color: var(--gold); white-space: nowrap; }\r\ntd.c { text-align: center; }\r\n.fit { color: var(--ok); font-family: var(--mono); font-size: 12.5px; }\r\n.nofit { color: var(--faint); font-family: var(--mono); font-size: 12.5px; }\r\n.cell { font-family: var(--mono); font-size: 12.5px; color: var(--gold-light); white-space: nowrap; }\r\n\r\nul.plain, ol.plain { margin: 0; padding-left: 20px; display: grid; gap: 10px; max-width: 65ch; }\r\nul.plain li::marker { color: var(--gold); }\r\nol.plain li::marker { color: var(--gold); font-family: var(--mono); font-size: 12px; }\r\n.note { font-size: 13.5px; color: var(--muted); max-width: 65ch; }\r\n\r\n.split { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 14px; }\r\n.panel { border: 1px solid var(--hair-soft); background: var(--card); border-radius: 2px; padding: 18px 20px; display: grid; gap: 10px; align-content: start; min-width: 0; }\r\n.panel h3 { font-size: 19px; }\r\n.panel ul { margin: 0; padding-left: 18px; display: grid; gap: 8px; font-size: 14px; }\r\n.panel li::marker { color: var(--gold); }\r\n\r\n.files { display: flex; flex-wrap: wrap; gap: 8px; }\r\n.files span { font-family: var(--mono); font-size: 12.5px; color: var(--warm); border: 1px solid var(--hair); border-radius: 2px; padding: 4px 10px; }\r\n\r\nfooter { border-top: 1px solid var(--hair-soft); padding-top: 20px; font-size: 13px; color: var(--muted); display: grid; gap: 6px; }\r\na { color: var(--gold); }\r\na:focus-visible { outline: 2px solid var(--gold-light); outline-offset: 2px; }\r\n</style>\r\n</head>\r\n<body>\r\n\r\n<main class=\"page\">\r\n\r\n  <header>\r\n    <div class=\"kicker\">The Themata Project · Phase 5 draft</div>\r\n    <h1>Chrysippus's themata, machine checked</h1>\r\n    <p class=\"lede\">Which of Chrysippus's reduction rules, the <span class=\"greek\">θέματα</span>, under which readings of the Stoic connectives, derive exactly the arguments the ancient sources accept and none of the ones they reject?</p>\r\n    <div class=\"status\"><strong>Not for publication</strong> Draft for specialist review. Kyle has signed off 9 of the 38 ledger entries (S001-S007, S009, S020), so every result here is still provisional.</div>\r\n  </header>\r\n\r\n  <section aria-labelledby=\"q\">\r\n    <div class=\"kicker\" id=\"q\">The question</div>\r\n    <p class=\"question\">Chrysippus held that every syllogistic argument is one of five indemonstrables, or reduces to them by four meta rules. Some of those rules survive in the sources. The rest are modern reconstructions.</p>\r\n    <p>The brief allowed three outcomes: one reconstruction fits uniquely, several fit, or none fit. Every candidate was run against a ledger of argument forms quoted from verified sources, and each verdict was checked in Lean 4.</p>\r\n  </section>\r\n\r\n  <section aria-labelledby=\"a\">\r\n    <div class=\"kicker\" id=\"a\">The answer</div>\r\n    <h2>Several fit, so the evidence underdetermines the themata. It still fixes three features of the logic.</h2>\r\n    <div class=\"figures\">\r\n      <div class=\"figure\"><div><span class=\"num\">164</span><span class=\"of\">of 804</span></div><div class=\"what\">candidate-settings fit the ledger. Every one is proven: each derivation found, each rejection covered by a theorem.</div></div>\r\n      <div class=\"figure\"><div><span class=\"num\">51</span><span class=\"of\">of 67</span></div><div class=\"what\">candidate rule sets fit under at least one setting. Every one of them has a first thema.</div></div>\r\n      <div class=\"figure\"><div><span class=\"num\">586</span><span class=\"of\">of 640</span></div><div class=\"what\">non-fits are proven not to fit. The other 54 fail only on bounded search, so 158 is a proven lower bound.</div></div>\r\n    </div>\r\n\r\n    <div class=\"findings\">\r\n      <div class=\"finding\">\r\n        <h3>The first thema is required</h3>\r\n        <p>Origen reports the \"two conditionals\" argument as a Stoic form, with the Stoics' own example: if you know that you are dead, you are dead; if you know that you are dead, you are not dead; therefore you do not know that you are dead. No candidate without a first thema derives it, and that is proved. So the attested third thema alone does not fit.</p>\r\n      </div>\r\n      <div class=\"finding\">\r\n        <h3>Contraction is needed, and weakening never happens</h3>\r\n        <p>Every fit lets a repeated premise count once, through the set view or the merging cut. No candidate under any setting derives the redundant argument (S016). A relevance semantics, where contraction holds and weakening fails, proves it.</p>\r\n      </div>\r\n      <div class=\"finding\">\r\n        <h3>The contradictory must cancel a negation</h3>\r\n        <p>Every fit reads the contradictory of \"not p\" as p. Read it as \"not not p\" and the Sorites chain (S018) is provably underivable, in a Gödel logic where double negation does not collapse.</p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <section aria-labelledby=\"w\">\r\n    <div class=\"kicker\" id=\"w\">The new witness</div>\r\n    <p class=\"question\">\"The concrete example which the Stoics give to illustrate this form of argument is the following: 1st, If you know that you are dead, you are dead; 2d, if you know that you are dead, you are not dead. And the conclusion is, 'you do not know that you are dead.'\"</p>\r\n    <p class=\"note\">Origen, <em>Against Celsus</em> VII.15, translated by Frederick Crombie, Ante-Nicene Fathers IV (1885). Origen calls the form \"the theorem of two propositions\". The general schema sentence rests on an editorial emendation (the translators' note 4701); the Stoic example does not.</p>\r\n  </section>\r\n\r\n  <section aria-labelledby=\"n\">\r\n    <div class=\"kicker\" id=\"n\">The named candidates</div>\r\n    <p>Where each fits, under the toggle contradictory. Every fit is the same under Chrysippus's and Antipater's single premise policy, so the suite does not separate them.</p>\r\n    <div class=\"frame\">\r\n      <table>\r\n        <thead><tr><th>Candidate</th><th>Rules</th><th>List</th><th>Multiset</th><th>Set</th></tr></thead>\r\n        <tbody>\r\n          <tr><td>Attested</td><td>Third thema (Simplicius)</td><td class=\"c nofit\">no</td><td class=\"c nofit\">no</td><td class=\"c nofit\">no</td></tr>\r\n          <tr><td>Mates</td><td>First and third themata</td><td class=\"c nofit\">no</td><td class=\"c nofit\">no</td><td class=\"c fit\">fits</td></tr>\r\n          <tr><td>Mates + dialectical theorem</td><td>First, merging cut, third</td><td class=\"c nofit\">no</td><td class=\"c fit\">fits</td><td class=\"c fit\">fits</td></tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n    <p class=\"note\">Premise views say how an argument's premises are compared: in order (list), with repeats counted (multiset), or as a set.</p>\r\n  </section>\r\n\r\n  <section aria-labelledby=\"p\">\r\n    <div class=\"kicker\" id=\"p\">How \"underivable\" is established</div>\r\n    <p>Searching and not finding proves nothing. A failure counts as proven only when a Lean theorem covers it, and none of these uses <code>sorry</code>.</p>\r\n    <div class=\"frame\">\r\n      <table>\r\n        <thead><tr><th>Cell</th><th>Route</th><th>Covers</th></tr></thead>\r\n        <tbody>\r\n          <tr><td class=\"cell\">■cm</td><td>Every rule preserves classical truth, so a classical countermodel rules an argument out.</td><td>S006, S007; S014 under Chrysippus</td></tr>\r\n          <tr><td class=\"cell\">■rm</td><td>Every rule preserves validity in the relevance logic RM (Sugihara model), where premises fuse and weakening fails.</td><td>S016, S008, under every setting</td></tr>\r\n          <tr><td class=\"cell\">■cl</td><td>Cut preserves truth under any assignment closed under the base cases. Contraposition does not.</td><td>S020, for every candidate without a first thema</td></tr>\r\n          <tr><td class=\"cell\">■g3</td><td>Under the \"not not p\" reading, every rule is sound in three valued Gödel logic.</td><td>The Sorites under that reading</td></tr>\r\n          <tr><td class=\"cell\">■2</td><td>Without cut, contraposition keeps two premises.</td><td>Three premise items, for cut free candidates</td></tr>\r\n          <tr><td class=\"cell\">■rel</td><td>Without the merging cut, no atom can stand in exactly one place.</td><td>S011, for non merging candidates</td></tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n    <p class=\"note\">The relevance semantics and the closed valuations are proof devices. They are not claims about the logic the Stoics held.</p>\r\n  </section>\r\n\r\n  <section aria-labelledby=\"r\">\r\n    <div class=\"kicker\" id=\"r\">Results in detail</div>\r\n    <ul class=\"plain\">\r\n      <li><strong>No overgeneration anywhere.</strong> No candidate under any setting derives what the ledger rejects, and every such cell is proven.</li>\r\n      <li><strong>Fits by view.</strong> 102 fits use the set view. The other 62 use the merging cut, 52 under multiset and 10 under list. All 164 use the toggle contradictory.</li>\r\n      <li><strong>Sixteen candidates never fit.</strong> Seven lack a third thema, which the composite arguments need. Nine lack a first thema, which S020 needs.</li>\r\n      <li><strong>Redundancy.</strong> S016 is valid by the Stoic validity criterion (Diogenes Laertius 7.77) under every reading of the conditional, so its rejection rests on redundancy alone. S009 and S011 are redundant under the strict reading and not under the narrow one. The ledger is consistent only if indifferently concluding arguments were exempt.</li>\r\n      <li><strong>Asserted falsity is not negation.</strong> S008, \"'p and q' is false; p; therefore not q\", which Diogenes calls conclusive but not syllogistic, is proven underivable by every candidate, as the ledger requires.</li>\r\n    </ul>\r\n  </section>\r\n\r\n  <section aria-labelledby=\"o\">\r\n    <div class=\"kicker\" id=\"o\">Open and underdetermined</div>\r\n    <div class=\"split\">\r\n      <div class=\"panel\">\r\n        <h3>What the evidence cannot yet decide</h3>\r\n        <ul>\r\n          <li>The shape of the first thema, which premise it contraposes, and the shape of the cut: every variant fits somewhere.</li>\r\n          <li>A separate second or fourth thema: no attested argument in the ledger needs one beyond contraposition and cut.</li>\r\n          <li>Chrysippus against Antipater on single premise arguments, by how those items were ruled.</li>\r\n        </ul>\r\n      </div>\r\n      <div class=\"panel\">\r\n        <h3>Bobzien's reconstruction</h3>\r\n        <ul>\r\n          <li>An earlier summary reported Bobzien's reconstruction as monotonic and without contraction, the opposite of every fit here. Her paper, read in full, says the reverse: monotonicity fails because of the redundancy restriction, and her second thema supplies contraction (Stoic Syllogistic, 1996, pp. 181-182). Encoded as a candidate (T1-T4, p. 153), she fits in all six toggle settings, under every premise view, and derives S011, S012 and S020 as she analyses them. Her profile is identical, cell for cell, to two generated candidates (contraposition of either premise plus a merging cut), so she does not narrow the answer.</li>\r\n        </ul>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <section aria-labelledby=\"l\">\r\n    <div class=\"kicker\" id=\"l\">Limits</div>\r\n    <ul class=\"plain\">\r\n      <li>The ledger is small, 17 formal items, and mostly unsigned (9 of 38 entries signed off). Every argument form now quotes a primary text: Sextus (Bury's Loeb) and Alexander (Wallies) are stored for research. Galen is still missing, and some Alexander readings rest on emendation (S011, T04).</li>\r\n      <li>S020 rests on Origen, a later witness who is not a Stoic. Its quotation is verified against the stored text.</li>\r\n      <li>Mates is represented by a summary, not his text. Reading the dialectical theorem as a merging cut is our own interpretation.</li>\r\n      <li>The Sorites runs as a three link chain. Under the list view, results depend on the order in which the ledger lists premises.</li>\r\n      <li>Derivations shown by the harness are evaluations of the same rules the proofs are about, not kernel checked certificates, except two proved in Lean.</li>\r\n      <li>The search runs to depth 8 over each item's own formulas. Only the 54 unproven non-fits depend on these bounds.</li>\r\n      <li>The reading of Alexander on the synthetic theorem (T04) is our own reading of untranslated Greek and is pending review.</li>\r\n    </ul>\r\n  </section>\r\n\r\n  <section aria-labelledby=\"v\">\r\n    <div class=\"kicker\" id=\"v\">For the reviewer</div>\r\n    <h2>Seven questions</h2>\r\n    <ol class=\"plain\">\r\n      <li>Are the ledger verdicts right, especially S011 (valid), S016 (invalid; Sextus gives the redundant item as a conjunct), S008 (conclusive but not syllogistic), the Sorites form taken as valid, and S020 from Origen?</li>\r\n      <li>Is Origen's report of \"the theorem of two propositions\" good evidence that the Stoics treated the form as reducible by the themata, and does the emendation in note 4701 affect that?</li>\r\n      <li>Every fit needs a repeated premise to count once. Bobzien gets the same effect from her second thema and suggests doublets were removed before analysis. Is the set view a fair encoding of that practice?</li>\r\n      <li>Is reading the contradictory of \"not p\" as p the standard view, given Diogenes Laertius 7.69 on double negation?</li>\r\n      <li>Is our encoding of Simplicius's third thema, a cut with the conclusion first and one further premise, fair to the Greek?</li>\r\n      <li>Is reading the dialectical theorem as a merging cut defensible?</li>\r\n      <li>Did Alexander say the Stoics made their second, third and fourth themata from the synthetic theorem?</li>\r\n    </ol>\r\n    <p class=\"note\">The materials, in the Arete repository under <code>themata/</code>:</p>\r\n    <div class=\"files\"><span>FINDINGS.md</span><span>evidence/</span><span>NOTES.md</span><span>lean/</span><span>results/matrix.md</span></div>\r\n  </section>\r\n\r\n  <section aria-labelledby=\"b\">\r\n    <div class=\"kicker\" id=\"b\">Before anything is public</div>\r\n    <ol class=\"plain\">\r\n      <li>Kyle signs off the ledger entries, or amends them, and the matrix is regenerated.</li>\r\n      <li>A specialist in Stoic logic reviews the findings, the ledger and the encoding.</li>\r\n      <li>The remaining ancient texts named in the gaps are stored.</li>\r\n    </ol>\r\n  </section>\r\n\r\n  <footer>\r\n    <div>Lean 4.22.0 · 67 candidates · 12 settings · 17 formal items · search depth 8</div>\r\n    <div>Status as of 28 September 2026. Figures checked against the matrix.</div>\r\n  </footer>\r\n\r\n</main>\r\n</body>\r\n</html>\r\n"
